import collections,hashlib,json
from pathlib import Path
source=Path('/private/tmp/fq-application-gap-observations-20261122.json');p=json.loads(source.read_text());assert p['completed'] and len(p['rows'])==1200
accepted=[r for r in p['rows'] if r['status']=='accepted'];lookup={(r['case'],r['seed'],r['workflow']):r for r in accepted};seeds=p['manifest']['compiler_seeds'];new={i['case'] for i in p['inputs'] if i['source_target_is_new']}
def quality(row):
 m=row['metrics'];return m['full_cz_count'],m['two_body_dependency_depth']
def outcome(a,b):
 return 'equal' if a==b else 'dominates' if all(x<=y for x,y in zip(a,b)) else 'dominated' if all(x>=y for x,y in zip(a,b)) else 'tradeoff'
comparisons=[];witnesses=[]
for fq in ('flagquantum-ordinary-restored','flagquantum-target-artifact'):
 for other in ('qiskit-transpile-restored','cirq-route-cz-restored'):
  pairs=collections.Counter();changed=collections.Counter();controls=collections.Counter();cases=collections.Counter();rows=[]
  for item in p['inputs']:
   case=item['case'];outcomes=[]
   for seed in seeds:
    a=lookup.get((case,seed,fq));b=lookup.get((case,seed,other))
    if a is None or b is None:continue
    x,y=quality(a),quality(b);label=outcome(x,y);pairs[label]+=1;(changed if case in new else controls)[label]+=1;outcomes.append(label)
    pair={'case':case,'seed':seed,'flagquantum_workflow':fq,'other_workflow':other,'flagquantum_cz_depth':x,'other_cz_depth':y,'outcome':label,'cz_excess':x[0]-y[0],'depth_excess':x[1]-y[1],'source_target_changed_from_01':case in new}
    rows.append(pair)
    if other=='qiskit-transpile-restored' and case in new and x[0]>y[0]:witnesses.append(pair)
   if outcomes:cases[outcomes[0] if len(set(outcomes))==1 else 'mixed']+=1
  comparisons.append({'flagquantum_workflow':fq,'other_workflow':other,'seed_pairs':dict(pairs),'changed_seed_pairs':dict(changed),'repeated_seed_pairs':dict(controls),'case_outcomes_across_all_seeds':dict(cases),'pairs':rows})
ordered=sorted(witnesses,key=lambda r:(-r['cz_excess'],-r['depth_excess'],r['case'],r['flagquantum_workflow'],r['seed']))
native=next(r for r in ordered if r['flagquantum_workflow']=='flagquantum-target-artifact')
variations={}
for name in p['manifest']['configurations']:
 sizes=collections.Counter(len({r['payload_sha256'] for r in accepted if r['case']==item['case'] and r['workflow']==name}) for item in p['inputs'])
 variations[name]=dict(sizes)
result={'evidence_class':'development','implementation_commit':p['implementation_commit'],'base_commit':p['base_commit'],'source_commit':p['source_commit'],'observation_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'completed_observations':len(p['rows']),'status_counts':dict(collections.Counter(r['status'] for r in p['rows'])),'source_target_changed_from_01':len(new),'repeated_source_target_controls':len(p['inputs'])-len(new),'max_semantic_error':max(r['metrics']['max_semantic_error'] for r in accepted),'normalized_output_variation':variations,'comparisons':comparisons,'prespecified_next_witness':ordered[0],'greatest_target_artifact_gap':native,'all_positive_changed_qiskit_gaps':ordered,'analysis_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'analysis_source':Path(__file__).read_text()}
Path('/private/tmp/fq-application-gap-analysis-20261122.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'witness':ordered[0],'native_gap':native,'observations':len(p['rows'])}))
